68	class CC_DLL PhysicsContact : public EventCustom
69	{
70	public:
71	    
72	    enum class EventCode
73	    {
74	        NONE,
75	        BEGIN,
76	        PRESOLVE,
77	        POSTSOLVE,
78	        SEPARATE
79	    };
80	    
81	    /** Get contact shape A. */
82	    PhysicsShape* getShapeA() const { return _shapeA; }
83	    
84	    /** Get contact shape B. */
85	    PhysicsShape* getShapeB() const { return _shapeB; }
86	    
87	    /** Get contact data. */
88	    const PhysicsContactData* getContactData() const { return _contactData; }
89	    
90	    /** Get previous contact data */
91	    const PhysicsContactData* getPreContactData() const { return _preContactData; }
92	    
93	    /** 
94	     * Get data. 
95	     * @lua NA
96	     */
97	    void* getData() const { return _data; }
98	    
99	    /**
100	     * @brief Set data to contact. 
101	     
102	     * You must manage the memory yourself, Generally you can set data at contact begin, and destroy it at contact separate.
103	     *
104	     * @lua NA
105	     */
106	    void setData(void* data) { _data = data; }
107	
108	    /** Get the event code */
109	    EventCode getEventCode() const { return _eventCode; };
110	
111	private:
112	    static PhysicsContact* construct(PhysicsShape* a, PhysicsShape* b);
113	    bool init(PhysicsShape* a, PhysicsShape* b);
114	    
115	    void setEventCode(EventCode eventCode) { _eventCode = eventCode; };
116	    bool isNotificationEnabled() const { return _notificationEnable; }
117	    void setNotificationEnable(bool enable) { _notificationEnable = enable; }
118	    PhysicsWorld* getWorld() const { return _world; }
119	    void setWorld(PhysicsWorld* world) { _world = world; }
120	    void setResult(bool result) { _result = result; }
121	    bool resetResult() { bool ret = _result; _result = true; return ret; }
122	    
123	    void generateContactData();
124	
125	private:
126	    PhysicsContact();
127	    ~PhysicsContact();
128	    
129	private:
